-- 296: Original BrillaPrep WASSCE BrillaPrep transitional Music beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_296_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_296_guard;
INSERT INTO _migration_296_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_016' AND NOT (q.topic_id IS 'topic_was_music_b005_4' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is a musical phrase?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ternary form","B. A single melodic line without independent harmony","C. It creates unity and helps listeners recognise developing material","D. A coherent unit of melody that suggests a point of rest"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A phrase groups notes into a meaningful musical thought, often shaped by breath, cadence or punctuation-like closure. Therefore the correct answer is D: A coherent unit of melody that suggests a point of rest.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_016' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_296_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_017' AND NOT (q.topic_id IS 'topic_was_music_b005_4' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which form follows the pattern A B A?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ternary form","B. A single melodic line without independent harmony","C. It creates unity and helps listeners recognise developing material","D. One part ascends while the other descends"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Ternary form presents a first section, contrasts it with a second, and then returns to the opening material. Therefore the correct answer is A: Ternary form.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_017' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_296_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_018' AND NOT (q.topic_id IS 'topic_was_music_b005_4' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What describes monophonic texture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It creates unity and helps listeners recognise developing material","B. A single melodic line without independent harmony","C. One part ascends while the other descends","D. A coherent unit of melody that suggests a point of rest"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Monophony may be sung or played by one or many performers in unison, but it contains only one melodic strand. Therefore the correct answer is B: A single melodic line without independent harmony.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_018' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_296_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_019' AND NOT (q.topic_id IS 'topic_was_music_b005_4' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is repetition of a motif useful in composition?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. One part ascends while the other descends","B. A coherent unit of melody that suggests a point of rest","C. It creates unity and helps listeners recognise developing material","D. Ternary form"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A recurring motif establishes identity while changes of pitch, rhythm or sequence can provide variety without losing coherence. Therefore the correct answer is C: It creates unity and helps listeners recognise developing material.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_019' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_296_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_020' AND NOT (q.topic_id IS 'topic_was_music_b005_4' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is contrary motion between two melodic parts?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A coherent unit of melody that suggests a point of rest","B. Ternary form","C. A single melodic line without independent harmony","D. One part ascends while the other descends"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Contrary motion sends the lines in opposite directions and can strengthen independence between voices. Therefore the correct answer is D: One part ascends while the other descends.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_020' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
